532	  ): Promise<ConcentrationFlag[]> {
533	    try {
534	      // Usar spendByWorker fornecido ou computar
535	      const workerSpend = spendByWorker ?? (await FinancialBIService.getSpendByWorker(companyId, period));
536	
537	      if (workerSpend.length === 0) return [];
538	
539	      const workerIds = workerSpend.map((w) => w.workerId);
540	
541	      // Buscar applications concluídas da empresa para os workers no período
542	      // (aplicações com status 'completed' ou 'in_progress' com checkout)
543	      const { data: jobs, error: jobsErr } = await supabase
544	        .from('jobs')
545	        .select('id, start_date')
546	        .eq('company_id', companyId)
547	        .gte('start_date', period.start)
