568	
569	      if (appsErr) {
570	        logError('financialBI.getConcentrationFlags.apps', appsErr);
571	        return [];
572	      }
573	
574	      // Agregar dias distintos por worker
575	      const daysMap = new Map<string, Set<string>>();
576	      for (const app of (apps ?? []) as Array<{ worker_id: string; job_id: string; status: string }>) {
577	        const startDate = jobDateMap.get(app.job_id);
578	        if (!startDate) continue;
579	        const dayStr = startDate.slice(0, 10); // YYYY-MM-DD
580	        if (!daysMap.has(app.worker_id)) daysMap.set(app.worker_id, new Set());
